begin;
insert into auth.users(id,email,email_confirmed_at) values('00000000-0000-4000-8000-000000000001','transfer@example.test',now()),('00000000-0000-4000-8000-000000000002','outsider@example.test',now());
insert into auth.sessions(id,user_id) values('30000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001'),('30000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000002');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claim.session_id','30000000-0000-4000-8000-000000000001',true);
select public.register_portal_session('Transfer fixture');
select set_config('test.bakery',public.create_initial_bakery('Transfer bakery','Main')::text,true);
reset role;
update public.saas_subscriptions set plan_code='growth' where bakery_id=current_setting('test.bakery')::uuid;
set local role authenticated;
do $$ declare b uuid:=current_setting('test.bakery')::uuid;a uuid;dest uuid;i uuid;l uuid;t uuid;c uuid;req uuid:=gen_random_uuid();creq uuid:=gen_random_uuid();day date:=(statement_timestamp() at time zone 'America/Lima')::date;begin
 select id into a from public.branches where bakery_id=b;
 insert into public.branches(bakery_id,name) values(b,'Other') returning id into dest;
 insert into public.ingredients(bakery_id,name,unit,reference_cost) values(b,'Harina','kg',2) returning id into i;
 perform public.record_lot_movement(b,a,i,gen_random_uuid(),'in',3,'Entry','EARLY',day+2,null);
 perform public.record_lot_movement(b,a,i,gen_random_uuid(),'in',7,'Entry','LATE',day+20,null);
 t:=public.transfer_inventory(b,a,dest,i,req,5,'Restock');
 if t<>public.transfer_inventory(b,a,dest,i,req,5,'Restock') then raise exception 'Duplicate transfer';end if;
 if (select quantity from public.stock_balances where branch_id=a and ingredient_id=i)<>5 or (select quantity from public.stock_balances where branch_id=dest and ingredient_id=i)<>5 then raise exception 'Wrong balances';end if;
 if (select sum(quantity) from public.stock_lots where branch_id=dest and lot_code='EARLY' and expires_on=day+2)<>3 or (select count(*) from public.inventory_transfer_lines where transfer_id=t)<>2 then raise exception 'Lot metadata lost';end if;
 begin perform public.transfer_inventory(b,a,dest,i,gen_random_uuid(),6,'Insufficient');raise exception 'Oversold';exception when check_violation then null;end;
 select id into l from public.stock_lots where branch_id=dest and lot_code='EARLY';
 c:=public.reconcile_inventory(b,dest,l,creq,3,2,'Physical count');
 if c<>public.reconcile_inventory(b,dest,l,creq,3,2,'Physical count') then raise exception 'Duplicate count';end if;
 begin perform public.reconcile_inventory(b,dest,l,gen_random_uuid(),3,1,'Stale');raise exception 'Stale accepted';exception when serialization_failure then null;end;
 perform public.reconcile_inventory(b,dest,l,gen_random_uuid(),2,4,'Surplus');
 if (select sum(quantity) from public.stock_lots where branch_id=dest and lot_code='EARLY')<>4 or (select quantity from public.stock_balances where branch_id=dest and ingredient_id=i)<>6 then raise exception 'Count mismatch';end if;
 if (select count(*) from public.inventory_counts)<>2 or (select count(*) from public.inventory_transfers)<>1 then raise exception 'Duplicate record';end if;
 perform set_config('test.from',a::text,true);perform set_config('test.to',dest::text,true);perform set_config('test.ingredient',i::text,true);
end $$;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select set_config('request.jwt.claim.session_id','30000000-0000-4000-8000-000000000002',true);
select public.register_portal_session('Outside');
do $$ begin
 if exists(select 1 from public.inventory_transfers) or exists(select 1 from public.inventory_counts) then raise exception 'Data leak';end if;
 begin perform public.transfer_inventory(current_setting('test.bakery')::uuid,current_setting('test.from')::uuid,current_setting('test.to')::uuid,current_setting('test.ingredient')::uuid,gen_random_uuid(),1,'Denied');raise exception 'Cross tenant';exception when insufficient_privilege then null;end;
end $$;
rollback;
